class Solution:
    def doesAliceWin(self, s: str) -> bool:
        vowels = set('aeiou')
        total_vowels = 0

        for char in s:
            if char in vowels:
                total_vowels += 1

        # Alice wins if there is at least one vowel
        # because she can always remove a substring with odd vowels
        # If there are no vowels, Alice has no valid move
        return total_vowels > 0

